(()=>{if(document.body.dataset.workspace!=='visual')return;const $=id=>document.getElementById(id),q=s=>document.querySelector(s),zh=()=>document.documentElement.lang!=='en';const api=async(p,o={})=>{const r=await fetch(p,o),b=await r.json().catch(()=>({}));if(!r.ok)throw Error(b.error||'Request failed');return b};const project=()=>new URLSearchParams(location.search).get('project');const copy=()=>zh()?{name:'项目名称',complete:'完成',confirm:'完成后将保存当前图片为最终成品，项目将不能继续修改。确定完成？',done:'已完成',editing:'编辑中',renamed:'项目名称已更新。'}:{name:'Project name',complete:'Complete',confirm:'This saves the current image as the final artwork. This project can no longer be edited. Continue?',done:'Completed',editing:'Editing',renamed:'Project name updated.'};function latest(state){const rows=(state.conversation||[]).filter(x=>x?.type!=='workspace_state');const row=rows.at(-1);return (row?.images||[]).at(-1)||null}async function updateTitle(){const id=project(),input=$('projectName');if(!id||!input?.value.trim())return;await api('/api/member/projects',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,title:input.value.trim(),locale:zh()?'zh':'en'})});q('#workspaceStatus').textContent=copy().renamed}async function complete(){const id=project();if(!id){q('#saveProject')?.click();setTimeout(complete,900);return}if(!confirm(copy().confirm))return;const data=await api('/api/member/projects?id='+encodeURIComponent(id));const state=data.conversation.find(x=>x?.type==='workspace_state'&&x.workspace==='visual');if(!state)throw Error('Project workspace state is missing.');state.status='completed';state.finalImage=latest(data);await api('/api/member/projects',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,title:$('projectName')?.value.trim()||data.title,locale:data.locale,conversation:[state,...data.conversation.filter(x=>x?.type!=='workspace_state')]})});location.reload()}function refresh(){const id=project(),results=$('workspaceResults');if(!results)return;let button=$('completeVisualProject');if(!button){button=document.createElement('button');button.id='completeVisualProject';button.type='button';button.className='secondary';button.onclick=()=>complete().catch(e=>q('#workspaceStatus').textContent=e.message);q('.visual-result-actions')?.append(button)}button.textContent=copy().complete;if(id)api('/api/member/projects?id='+encodeURIComponent(id)).then(data=>{const state=data.conversation.find(x=>x?.type==='workspace_state'&&x.workspace==='visual');if($('projectName')&&!$('projectName').value)$('projectName').value=data.title||'';if(state?.status==='completed'){button.hidden=true;qAll('.visual-result-actions button').forEach(b=>{if(/继续修改|refine|保存修改|save changes/i.test(b.textContent))b.hidden=true});document.body.classList.remove('visual-editing');q('#workspaceResults h2').textContent=copy().done;q('#workspaceResults p').textContent=zh()?'最终成品已锁定，可查看大图或下载。':'Final artwork is locked. View or download it.';q('#visualTaskPanel')?.setAttribute('hidden','');q('#visualUploadPanel')?.setAttribute('hidden','')}}).catch(()=>{})}const qAll=s=>Array.from(document.querySelectorAll(s));$('projectName')?.addEventListener('change',()=>updateTitle().catch(e=>q('#workspaceStatus').textContent=e.message));new MutationObserver(refresh).observe(document.body,{childList:true,subtree:true});refresh()})();
